# Query to prepare data so the migration can be validated
TWO_BAD_DELETED_STUDY_ACRONYM_FIELDS = r"""
MATCH (:StudyRoot)-[:LATEST]-(sv:StudyValue)-[sv_ss]-(ss:StudyField)-[ss_sa:AFTER]-(sa:StudyAction)<-[:AUDIT_TRAIL]-(sr:StudyRoot) 
WHERE 
not exists((sa)-[:BEFORE]-()) 
AND ss.field_name = "study_acronym"
WITH *
LIMIT 2
// DISCONNECT OLD NODE
DELETE sv_ss
//CREATE EXTRA NODES FOR NEW NODE
CREATE (new_sa:StudyAction:Delete:TEST{status:"DRAFT", date: datetime({epochMillis: apoc.date.currentTimestamp()}) , user_initials:"Unkown-User"})-[:BEFORE]->(ss)
//CONNECT OLD NODE
CREATE (sr)-[:AUDIT_TRAIL]->(new_sa);
"""


